// Reject bad input before it can cost money.
const body = $input.first().json.body ?? $input.first().json;
const required = ['title', 'scenes'];
const missing = required.filter((k) => body[k] === undefined);
if (missing.length) {
  return [{ json: { ok: false, status: 400, error: `missing fields: ${missing.join(', ')}` } }];
}
if (!Array.isArray(body.scenes) || body.scenes.length === 0) {
  return [{ json: { ok: false, status: 400, error: 'scenes must be a non-empty array' } }];
}
const bad = body.scenes.filter((s) => !s.scene_id || !s.visual_prompt);
if (bad.length) {
  return [{ json: { ok: false, status: 400, error: `${bad.length} scene(s) missing scene_id or visual_prompt` } }];
}
const slug = body.slug || body.title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const engine = body.engine || $env.DEFAULT_ENGINE || 'wan22_flf2v';
const limit = body.limit ? ` --limit ${Number(body.limit)}` : '';
const storyboardJson = JSON.stringify({ ...body, slug }, null, 2).replace(/'/g, `'\\''`);
return [{
  json: {
    ok: true,
    slug,
    engine,
    sceneCount: body.scenes.length,
    writeCmd: `mkdir -p {{$env.PIPELINE_REPO}}/projects/${slug} && cat > {{$env.PIPELINE_REPO}}/projects/${slug}/storyboard.json <<'JSON'\n${storyboardJson}\nJSON`,
    planCmd: `cd {{$env.PIPELINE_REPO}} && python3 -m scripts.video_pipeline.cli plan ${slug} --engine ${engine} --json`,
    runCmd: `cd {{$env.PIPELINE_REPO}} && python3 -m scripts.video_pipeline.cli run ${slug} --engine ${engine}${limit} --json`,
    verifyCmd: `cd {{$env.PIPELINE_REPO}} && python3 -m scripts.video_pipeline.cli verify ${slug} --json`
  }
}];

// Parse CLI JSON output; surface failures instead of swallowing them.
const pick = (node) => {
  try { return JSON.parse($(node).first().json.stdout || '{}'); } catch (e) { return { parseError: String(e) }; }
};
const run = pick('Render (resumable)');
const verify = pick('Verify gate');
const ok = Boolean(verify.ok) && !(run.run?.failures?.length);
return [{
  json: {
    ok,
    status: ok ? 200 : 500,
    project: run.run?.project ?? null,
    scenesProcessed: run.run?.scenes_processed ?? 0,
    final: run.run?.assembly?.final ?? null,
    durationSeconds: run.run?.assembly?.duration ?? 0,
    costUsd: run.run?.state?.cost_usd ?? 0,
    issues: verify.issues ?? [],
    resumeHint: ok ? null : `Re-POST the same storyboard (or run cli resume ${run.run?.project ?? '<slug>'}) -- finished scenes are reused.`
  }
}];
